import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
/**
 * Per-session credentials under a per-boot key that is never sent. Holding
 * one session's credential, or any secret the serve host hands out, mints no
 * other session's.
 */
export class SessionCredentials {
    constructor() {
        this.key = randomBytes(32);
    }
    for(sessionId) {
        return createHmac("sha256", this.key).update(sessionId).digest("hex");
    }
    /** Whether `presented` is the credential of `sessionId`. */
    verifies(sessionId, presented) {
        if (sessionId === null || sessionId === "" || presented === null || presented === undefined) {
            return false;
        }
        const given = Buffer.from(presented);
        const expected = Buffer.from(this.for(sessionId));
        return given.length === expected.length && timingSafeEqual(given, expected);
    }
}
/** Query parameter carrying a session's credential to the tool MCP endpoint. */
export const TOOL_SESSION_CREDENTIAL_PARAM = "agentkitSessionCredential";
